package com.bank.monitor;

import java.util.Map;
import java.util.TreeMap;

// A metric name plus its labels. Two LabelSets are equal iff all labels match,
// which is exactly how Prometheus identifies a unique time-series.
public class LabelSet {
    private final String metricName;
    private final Map<String, String> labels;

    public LabelSet(String metricName, Map<String, String> labels) {
        this.metricName = metricName;
        this.labels = new TreeMap<>(labels);   // sorted for stable identity
    }

    // The unique series key — metric name plus sorted labels.
    public String seriesKey() {
        return metricName + labels.toString();
    }
}
