package com.bank.monitor;

import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

// Models the TSDB: one stored series per unique LabelSet. Grows without bound
// if a high-cardinality label is used.
public class MetricSeriesStore {
    private static final Logger log = Logger.getLogger(MetricSeriesStore.class.getName());
    private final Set<String> series = new HashSet<>();

    public void record(LabelSet labelSet) {
        boolean isNew = series.add(labelSet.seriesKey());
        if (isNew && series.size() % 100000 == 0) {
            log.warning(() -> "TSDB now holding " + series.size() + " series — memory climbing");
        }
    }

    public int seriesCount() { return series.size(); }
}
