package com.bank.monitor;

import java.util.logging.Logger;

// Rejects a metric design whose projected series count exceeds the budget.
public class CardinalityGuard {
    private static final Logger log = Logger.getLogger(CardinalityGuard.class.getName());

    private final int budget;   // max series this metric may produce

    public CardinalityGuard(int budget) {
        this.budget = budget;
    }

    // projectedSeries = product of distinct values of every label.
    public boolean approve(String metricName, long projectedSeries, String riskyLabel) {
        if (projectedSeries > budget) {
            log.severe(() -> "REJECT metric '" + metricName + "': projected " + projectedSeries
                    + " series exceeds budget " + budget
                    + (riskyLabel != null ? " — offending label '" + riskyLabel
                       + "' is high-cardinality. Move it to LOGS/TRACES." : ""));
            return false;
        }
        log.info(() -> "APPROVE metric '" + metricName + "': " + projectedSeries
                + " series within budget " + budget);
        return true;
    }
}
