package com.bank.monitor;

import java.util.Map;
import java.util.logging.*;

// Runnable demo: the explosion with account_id, then the safe version with account_type.
public class CardinalityDemo {
    private static final Logger log = Logger.getLogger(CardinalityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — cardinality explosion demo");

        CardinalityGuard guard = new CardinalityGuard(1000);   // budget: 1000 series

        // BAD design: label every transfer with the account_id.
        // 2,000,000 accounts × 2 statuses = 4,000,000 series.
        long badSeries = 2_000_000L * 2;
        guard.approve("transfers_total (with account_id)", badSeries, "account_id");

        // Simulate the TSDB filling up with per-account series (scaled down for the demo).
        MetricSeriesStore store = new MetricSeriesStore();
        for (int acct = 0; acct < 300_000; acct++) {
            String accountId = (acct % 2 == 0 ? "SAV" : "CUR") + acct;
            store.record(new LabelSet("transfers_total",
                Map.of("service", "transfer", "status", "success", "account_id", accountId)));
        }
        log.severe("Explosion: TSDB holds " + store.seriesCount()
                 + " series from account_id alone — Prometheus heading for OOM.");

        // GOOD design: drop account_id, keep bounded account_type (savings/current).
        // 2 account types × 2 statuses × 1 service = 4 series. account_id -> logs/traces.
        long goodSeries = 2L * 2 * 1;
        guard.approve("transfers_total (with account_type)", goodSeries, null);

        log.info("[trace=a3f91c20] account_id=SAV2001 amount=50000 -> this detail lives in LOGS, not a metric label");
    }
}
